package com.example.padelbackend.model;

import java.time.LocalTime;

public class Site {

	private int ID;
	private String Nom;
	private String Adresse;
	private LocalTime HeureOuverture;
	private LocalTime HeureFermeture;

	public Site() {
	}

	public Site(int ID, String nom, String adresse, LocalTime heureOuverture, LocalTime heureFermeture) {
		this.ID = ID;
		this.Nom = nom;
		this.Adresse = adresse;
		this.HeureOuverture = heureOuverture;
		this.HeureFermeture = heureFermeture;
	}

	public int getID() {
		return ID;
	}

	public void setID(int ID) {
		this.ID = ID;
	}

	public String getNom() {
		return Nom;
	}

	public void setNom(String nom) {
		this.Nom = nom;
	}

	public String getAdresse() {
		return Adresse;
	}

	public void setAdresse(String adresse) {
		this.Adresse = adresse;
	}

	public LocalTime getHeureOuverture() {
		return HeureOuverture;
	}

	public void setHeureOuverture(LocalTime heureOuverture) {
		this.HeureOuverture = heureOuverture;
	}

	public LocalTime getHeureFermeture() {
		return HeureFermeture;
	}

	public void setHeureFermeture(LocalTime heureFermeture) {
		this.HeureFermeture = heureFermeture;
	}

	// Compatibility aliases used by existing code/tests.
	public int getId() {
		return getID();
	}

	public void setId(int id) {
		setID(id);
	}
}

package com.example.padelbackend.model;

public class Terrain {

	private int ID;
	private int IDterrain;
	private String Nom;
	private int SiteID;

    // Constructors
    public Terrain() {
    }

    public Terrain(int ID, String nom, int siteID) {
        this.ID = ID;
        this.Nom = nom;
        this.SiteID = siteID;
    }

    // Getters and Setters
    public int getID() {
        return ID;
    }

    public void setID(int ID) {
        this.ID = ID;
    }

    public int getIDterrain() {
        return IDterrain;
    }

    public void setIDterrain(int ID_terrain) {
        this.IDterrain = ID_terrain;
    }

    public String getNom() {
        return Nom;
    }

    public void setNom(String nom) {
        this.Nom = nom;
    }

    public int getSiteID() {
        return SiteID;
    }

    public void setSiteID(int siteID) {
        SiteID = siteID;
    }
}

